def skill():
    prev = {5}
    for _ in range(4):
        nxt = set()
        for v in prev:
            nxt.add(2 * v)
            if v - 3 >= 1 and (v - 3) % 2 == 1:
                nxt.add(v - 3)
        prev = nxt
    return sum(prev)

def f(a):
    return a // 2 if a % 2 == 0 else a + 3

def standard():
    tot = 0
    for a1 in range(1, 5000):
        a = a1
        for _ in range(4):
            a = f(a)
        if a == 5:
            tot += a1
    return tot

def unique():
    return [sum(a1 for a1 in range(1, 30000) if (lambda x: [x := f(x) for _ in range(4)][-1])(a1) == 5)]
